import sys

def main():
    L = int(sys.stdin.readline().strip())
    R = int(sys.stdin.readline().strip())

    blocks = []
    current_level = 0
    current_count = 0

    while L <= R:
        segment_length = 10 ** (2 ** current_level)
        if L + segment_length - 1 > R:
            segment_length = R - L + 1

        if current_count == 0:
            current_count += 1
        elif blocks[-1][0] == current_level:
            blocks[-1][1] += 1
        else:
            blocks.append([current_level, 1])

        L += segment_length
        current_level += 1

    n = len(blocks)
    print(n)
    for t, c in blocks:
        print(t, c)

if __name__ == "__main__":
    main()
